<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();
if(page_post()){check_csrf();$name=trim((string)($_POST['name']??''));$type=(string)($_POST['type']??'other');$description=trim((string)($_POST['description']??''));$price=(int)($_POST['price']??0);$stock=($_POST['stock']??'')===''?null:(int)$_POST['stock'];
if($name===''||!in_array($type,['hat','shirt','pants','tshirt','face','head','other'],true)||$price<0||$price>50000||($stock!==null&&($stock<0||$stock>10000))){notice('Check the item name, type, price and stock.','error');go('/My/CreateItem.php');}
$q=$db->prepare('SELECT COUNT(*) FROM catalog_items WHERE creator_id=?');$q->execute([$currentUser['id']]);if((int)$q->fetchColumn()>=25){notice('You can have up to 25 catalog listings.','error');go('/My/CreateItem.php');}
$q=$db->prepare('INSERT INTO catalog_items(name,type,description,price,creator_id,stock) VALUES(?,?,?,?,?,?)');$q->execute([$name,$type,$description,$price,$currentUser['id'],$stock]);notice('Catalog listing published.');go('/Item.php?id='.$db->lastInsertId());}
page_start('Create Catalog Item');?><section class="Panel narrow"><h1>Create Catalog Item</h1><p>Create a simple listing. Image/texture uploads and real avatar rendering are not part of this phase.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Name<input name="name" maxlength="120" required></label><label>Type<select name="type"><?php foreach(['hat','shirt','pants','tshirt','face','head','other'] as $t):?><option value="<?=e($t)?>"><?=e(ucfirst($t))?></option><?php endforeach;?></select></label><label>Description<textarea name="description" maxlength="2000"></textarea></label><label>Price in Tickets<input type="number" name="price" min="0" max="50000" value="0" required></label><label>Stock (leave blank for unlimited)<input type="number" name="stock" min="0" max="10000"></label><button class="Button">Publish item</button></form></section><?php page_end();?>